insert into public.curriculum_sources (id, organization, title, url, landing_url, doc_year, revision, retrieved_at, language, license_note, inspection_status, notes, covers)
values
  ('ca26eba8-d0ed-5647-a8ea-b173ab7d9aea', 'Curriculum Development Centre (CDC), Government of Nepal', 'Secondary Education Curriculum 2077, Grade 11–12 Part 1 (Compulsory Subjects), updated', 'https://giwmscdnone.gov.np/media/pdf_upload/Secondary%20Education%20Curriculum%2C%202077%20Grade%2011-12%20Part%201%20(Compulsory%20Subject)%20-%20Updated_rglgnsv.pdf', 'https://moecdc.gov.np/content/160/secondary-education-curriculum--2077-grade-11-12-part/', '2077 B.S.', 'updated', '2026-10-11', 'English and Nepali', 'Government curriculum document; CDC states all rights reserved. Used here for syllabus structure/alignment only — no verbatim bulk reproduction.', 'inspected-text-extracted', 'Contains the Nepali curriculum (pages in legacy font encoding — text extraction produced unusable output, no OCR available locally), the full English curriculum, and the Mathematics 2078 curriculum. English and Mathematics extracted with pdftotext -layout; Nepali recorded as an extraction gap.', '["Nepali (extraction failed)","English","Mathematics 2078"]'::jsonb),
  ('5983e177-78fc-5dc2-bcf7-0ed0f37214d0', 'Curriculum Development Centre (CDC), Government of Nepal', 'Secondary Education Curriculum 2076, Grade 11–12 Part 2 (Optional Subjects)', 'https://giwmscdnone.gov.np/media/pdf_upload/Secondary%20Education%20Curriculum%2C2076%20Grade%2011-12%20Part%202%20(Optional%20Subject)_25lxbj8.pdf', 'https://moecdc.gov.np/content/159/secondary-education-curriculum-2076-grade-11-12-part-2/', '2076 B.S.', null, '2026-10-11', 'English (with Nepali-medium headers)', 'Government curriculum document; used for syllabus structure/alignment only.', 'inspected-text-extracted', 'Physics curriculum extracted (scope and sequence with two-column Grade 11/12 tables). Also contains Law, Child Development, Psychology, Hospitality and Instructional Pedagogy curricula (not part of Akshar''s seeded subject catalog). Subject catalogue table confirms optional-subject codes.', '["Physics"]'::jsonb),
  ('8c49ce4f-90fd-5bf3-bf3f-3a367b07da97', 'Curriculum Development Centre (CDC), Government of Nepal', 'Secondary Education Curriculum 2076, Grade 11–12 Part 3 (Optional Subjects)', 'https://giwmscdnone.gov.np/media/pdf_upload/Secondary%20Education%20Curriculum%2C2076%20Grade%2011-12%20Part%203%20(Optional%20Subject)_va9njcf.pdf', 'https://moecdc.gov.np/content/158/secondary-education-curriculum-2076-grade-11-12-part-3/', '2076 B.S.', null, '2026-10-12', 'English (with Nepali-medium learning-outcome tables)', 'Government curriculum document; used for syllabus structure/alignment only.', 'inspected-text-extracted', 'Biology (Part A Botany / Part B Zoology) and Business Studies curricula extracted. Also contains Geography, Computer Science, Procedural Law and Legal Drafting curricula (not seeded in Akshar).', '["Biology","Business Studies"]'::jsonb),
  ('d4fb0c69-864e-52ec-b181-fd35930f8e7d', 'Curriculum Development Centre (CDC), Government of Nepal', 'Secondary Education Curriculum 2076, Grade 11–12 Part 4 (Optional Subjects)', 'https://giwmscdnone.gov.np/media/pdf_upload/Secondary%20Education%20Curriculum%2C2076%20Grade%2011-12%20Part%204%20(Optional%20Subject)_Eng._8zwvgdp.pdf', 'https://moecdc.gov.np/content/157/secondary-education-curriculum-2076-grade-11-12-part-4/', '2076 B.S.', null, '2026-10-12', 'English (with Nepali-medium learning-outcome tables)', 'Government curriculum document; used for syllabus structure/alignment only.', 'inspected-text-extracted', 'Chemistry curriculum extracted. Also contains Marketing, Fashion Designing and three law curricula (not seeded in Akshar).', '["Chemistry"]'::jsonb),
  ('acb5a89f-7a0e-57a4-93c3-6b7b4b6822fc', 'Curriculum Development Centre (CDC), Government of Nepal', 'Secondary Education Curriculum 2076, Grade 11–12 Part 5 (Optional Subjects)', 'https://giwmscdnone.gov.np/media/pdf_upload/Secondary%20Education%20Curriculum%2C%202076%20Grade%2011-12%20Part%205%20(Optional%20Subject)_txyddsj.pdf', 'https://moecdc.gov.np/content/156/secondary-education-curriculum-2076-grade-11-12-part-5/', '2076 B.S.', null, '2026-10-12', 'English and Nepali', 'Government curriculum document; used for syllabus structure/alignment only.', 'inspected-text-extracted', 'Downloaded and inventoried. Contains Basic Business Finance, Business Mathematics, Environmental Science, Library and Information Science, Apiculture and Sericulture, Applied Mathematics, General Law, Hotel Management, Plumbing and Wiring, and Mathematics 2078. None of these are in Akshar''s seeded subject catalog yet, so no content was ingested from this volume.', '[]'::jsonb),
  ('16450a36-191b-5442-b704-538dd3269f63', 'Curriculum Development Centre (CDC), Government of Nepal', 'Secondary Education Curriculum 2076, Grade 11–12 Part 6 (Optional Subjects, Nepali medium)', 'https://giwmscdnone.gov.np/media/pdf_upload/Secondary%20Education%20Curriculum%2C2076%20Grade%2011-12%20Part%206%20(Optional%20Subject)_xg6ijpn.pdf', 'https://moecdc.gov.np/content/155/secondary-education-curriculum-2076-grade-11-12-part-6/', '2076 B.S.', null, '2026-10-12', 'Nepali', 'Government curriculum document; used for syllabus structure/alignment only.', 'inspected-extraction-failed', 'Downloaded successfully but every page uses a legacy Nepali font without Unicode mapping; pdftotext output is unreadable garble and no OCR tooling is available in this environment. No content ingested. Needs OCR or a Unicode-mapped copy before use.', '[]'::jsonb),
  ('bd2c1d45-2e78-5068-b8b6-d6cf3cc51672', 'Institute of Engineering (IOE), Tribhuvan University', 'B.E./B.Arch. Entrance Examination syllabus 2083 (updated 2026-07-07)', 'https://portal.tu.edu.np/downloads/download3_2026_07_07_22_05_05.pdf', 'https://ioe.tu.edu.np/downloads?category=445', '2083 B.S.', 'updated 2026-07-07', '2026-10-11', 'English', 'Official examination syllabus; used for syllabus structure/alignment only.', 'inspected-text-extracted', 'Clean text extraction. Four subjects with numbered units and sub-topics: Mathematics (50 marks), Physics (40), Chemistry (30), English (20). Treated as the current IOE syllabus; no later version found on the IOE downloads page at retrieval time.', '["Mathematics","Physics","Chemistry","English"]'::jsonb),
  ('686486af-08f6-51dc-8d8e-35c149de3c2f', 'Medical Education Commission (MEC), Government of Nepal', 'Syllabus for Bachelor Level Common Entrance Examination 2020 (revised 2026)', 'https://mec.gov.np/uploads/shares/curriculumn/syllabus_bachelor_program_revised__2026.pdf', 'https://mec.gov.np/en/category/syllabus', '2020 B.S.', 'revised 2026', '2026-10-11', 'English', 'Official examination syllabus; used for syllabus structure/alignment only.', 'inspected-text-extracted', 'Unit/topic-wise content tables for MBBS/BDS common entrance: Zoology + Botany (80), Chemistry (50), Physics (50), Mental Agility Test (20). Revision year 2026 confirmed on the document.', '["Biology (Zoology + Botany)","Chemistry","Physics","Mental Agility Test"]'::jsonb),
  ('011bf181-3df7-5831-80b5-f05b102a44b5', 'National Examination Board (NEB), Government of Nepal', 'NEB curriculum portal and openly accessible model questions (IBS)', 'https://neb.gov.np/curriculum', 'https://ibs.neb.gov.np/course/view.php?id=7', '2082 B.S.', null, '2026-10-12', 'Nepali and English', 'NEB states its IBS model items are freely and openly accessible; terms for other NEB documents not separately stated.', 'discovered-not-inspected', 'https://neb.gov.np/curriculum returned HTTP 500 at retrieval time, so its exact contents could not be inventoried. NEB''s IBS portal provides Grade 12 model/released question items (compulsory English, compulsory Mathematics, optional Physics, optional Economics). Evidence so far: NEB publishes examination/assessment materials; CDC publishes the curriculum itself. No NEB document was ingested.', '[]'::jsonb),
  ('56decabb-8a5c-5df7-b0c9-fbaaa12b0c73', 'CEHRD / Sikai Chautari, Government of Nepal', 'Sikai Chautari open learning portal', 'https://learning.cehrd.gov.np/', null, '2082 B.S.', null, '2026-10-12', 'Nepali and English', 'No explicit open-content licence found; footer states All rights reserved. Link-only: no content copied into Akshar.', 'discovered-not-inspected', 'Free-access portal (no account required) with Grade 11/12 course pages and textbook/audio/video resources. Because no reuse licence is stated, nothing was imported; Akshar should only link to it.', '[]'::jsonb),
  ('05f654d7-7faf-5c92-a32e-dcd6cd5f11ec', 'Curriculum Development Centre (CDC), Government of Nepal', 'CDC e-library and textbook catalogue (Grade 11/12 shelves)', 'https://lib.moecdc.gov.np/elibrary/', 'http://lib.moecdc.gov.np/catalog/opac_css/index.php?lvl=etagere_see&id=21', '2082 B.S.', null, '2026-10-12', 'Nepali and English', 'Catalogue lists records as Public; CDC PDFs state all rights reserved. Link-only: no textbook content copied into Akshar.', 'discovered-not-inspected', 'Catalogue shelves confirm official Grade 11 and Grade 12 textbooks exist (English, Nepali, Social Studies). Individual e-copy links were not all resolvable at retrieval time and the host was intermittently unavailable. Not used as an ingestion source.', '[]'::jsonb)
