begin;

-- Pre-import: backfill grade_id for stream-placed subjects.
update public.subjects s
set grade_id = st.grade_id
from public.streams st
where s.stream_id = st.id
  and s.grade_id is null;

-- Curriculum sources (source registry, one row per official document).
on conflict (id) do update set
  organization = excluded.organization, title = excluded.title, url = excluded.url,
  landing_url = excluded.landing_url, doc_year = excluded.doc_year, revision = excluded.revision,
  retrieved_at = excluded.retrieved_at, language = excluded.language, license_note = excluded.license_note,
  inspection_status = excluded.inspection_status, notes = excluded.notes, covers = excluded.covers;

-- Curriculum versions.
