delete from public.units where curriculum_version_id = '54aff7f1-af24-59ab-8477-e5a3fabd62f6';

-- Units (syllabus groupings: content areas, parts, or numbered sections).
on conflict (id) do update set
  subject_id = excluded.subject_id, title = excluded.title, source_number = excluded.source_number,
  curriculum_version_id = excluded.curriculum_version_id, source_locator = excluded.source_locator,
  verification_status = excluded.verification_status, display_order = excluded.display_order;

-- Chapters.
on conflict (id) do update set
